sub read_file_in_chunks {
    my ($file, $chunk_size) = @_;
    $chunk_size //= 50000;
    open(my $fh, '<:raw', $file) or die "Cannot open $file: $!";
    my $buf;
    while(read($fh, $buf, $chunk_size)) {
        print $buf;
        print "\n---CHUNK_BOUNDARY---\n";
    }
    close($fh);
}

